package com.mantou.salesdialer.contacts;
import android.content.Context;import android.util.AtomicFile;import java.io.*;import java.nio.charset.StandardCharsets;import java.util.*;import org.json.*;
/** Separate from short engineering permits. Issuance requires a visible native confirmation. */
final class EnterpriseOperatorBatch {
 private static final Object LOCK=new Object();
 private static AtomicFile file(Context c){return new AtomicFile(new File(c.getFilesDir(),"enterprise-operator-batch.json"));}
 static boolean present(Context c){return file(c).getBaseFile().exists();}
 static void clear(Context c){synchronized(LOCK){file(c).delete();}}
 private static void save(AtomicFile f,JSONObject p)throws Exception{FileOutputStream out=f.startWrite();try{out.write(p.toString().getBytes(StandardCharsets.UTF_8));f.finishWrite(out);}catch(Exception e){f.failWrite(out);throw e;}}
 private static JSONObject permit(Context c)throws Exception{byte[] bytes=file(c).readFully();if(bytes.length>1048576)throw new IllegalStateException("BATCH_PERMIT_INVALID");JSONObject p=new JSONObject(new String(bytes,StandardCharsets.UTF_8));JSONArray ids=p.getJSONArray("targetIds");Set<String> distinct=new HashSet<>();for(int i=0;i<ids.length();i++)distinct.add(ids.getString(i));if(p.length()!=13||p.getInt("schema")!=3||!p.getString("purpose").equals("OPERATOR_BATCH")||!p.getString("id").matches("OPERATOR-[a-f0-9-]{36}")||!p.getString("signature").matches("[a-f0-9]{64}")||distinct.size()!=ids.length()||!OperatorBatchPolicy.valid(System.currentTimeMillis(),p.getLong("notBefore"),p.getLong("notAfter"),p.getInt("maxAttempts"),ids.length()))throw new IllegalStateException("BATCH_PERMIT_INVALID");return p;}
 static JSONObject install(Context c,JSONObject p,JSONObject status,String account)throws Exception{synchronized(LOCK){save(file(c),p);try{ready(c,status,status.getJSONObject("queue"),account);return new JSONObject().put("confirmed",true).put("targetCount",p.getInt("maxAttempts")).put("expiresAt",p.getLong("notAfter"));}catch(Exception e){clear(c);throw e;}}}
 static void ready(Context c,JSONObject status,JSONObject q,String account)throws Exception{synchronized(LOCK){JSONObject p=permit(c),actor=status.getJSONObject("actor"),active=status.optJSONObject("operatorBatch");if(!status.getString("mode").equals("LIVE")||active==null||!active.getString("id").equals(p.getString("id"))||!p.getString("queueId").equals(q.getString("id"))||!p.getString("tenantId").equals(actor.getString("tenantId"))||!p.getString("ownerId").equals(actor.getString("userId"))||!p.getString("deviceId").equals(EnterpriseSession.deviceId(c))||!p.getString("accountKey").equals(account)||used(c,p.getString("id"))>=p.getInt("maxAttempts"))throw new IllegalStateException("BATCH_CONFIRMATION_REQUIRED");}}
 private static int used(Context c,String id)throws Exception{AtomicFile f=new AtomicFile(new File(c.getFilesDir(),"enterprise-operator-use.json"));if(!f.getBaseFile().exists())return 0;JSONObject j=new JSONObject(new String(f.readFully(),StandardCharsets.UTF_8));if(j.length()!=2||j.getInt("used")<0||j.getInt("used")>10000)throw new IllegalStateException("BATCH_USE_INVALID");return id.equals(j.getString("id"))?j.getInt("used"):0;}
 static void consume(Context c,JSONObject status,JSONObject queue,JSONObject claim,String account)throws Exception{synchronized(LOCK){ready(c,status,queue,account);JSONObject p=permit(c);if(!p.getString("id").equals(claim.getString("permitId")))throw new IllegalStateException("BATCH_SCOPE_MISMATCH");JSONArray ids=p.getJSONArray("targetIds");boolean found=false;for(int i=0;i<ids.length();i++)if(ids.getString(i).equals(claim.getJSONObject("target").getString("id")))found=true;if(!found)throw new IllegalStateException("BATCH_SCOPE_MISMATCH");save(new AtomicFile(new File(c.getFilesDir(),"enterprise-operator-use.json")),new JSONObject().put("id",p.getString("id")).put("used",used(c,p.getString("id"))+1));}}
}
